package pe.edu.utp.thanosgym.auth.service;
import io.jsonwebtoken.Claims;import pe.edu.utp.thanosgym.auth.dto.*;import pe.edu.utp.thanosgym.auth.exception.ApiException;import pe.edu.utp.thanosgym.auth.model.*;import pe.edu.utp.thanosgym.auth.repository.UsuarioRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;
@Service @Transactional public class AutenticacionService{
 private final UsuarioRepository usuarios;private final PasswordEncoder encoder;private final JwtService jwt;private final int minutosBloqueo;public AutenticacionService(UsuarioRepository u,PasswordEncoder e,JwtService j,@Value("${thanosgym.auth.bloqueo-minutos:15}") int m){usuarios=u;encoder=e;jwt=j;minutosBloqueo=m;}
 public LoginResponse login(CredencialesRequest r){Usuario u=usuarios.findByUsuarioIgnoreCase(r.usuario()).orElseThrow(this::credenciales);if(!u.isActivo())throw credenciales();if(u.getBloqueadoHasta()!=null&&u.getBloqueadoHasta().isAfter(LocalDateTime.now()))throw new ApiException(HttpStatus.TOO_MANY_REQUESTS,"USUARIO_BLOQUEADO","Usuario bloqueado temporalmente hasta "+u.getBloqueadoHasta());if(!encoder.matches(r.password(),u.getPasswordHash())){u.setIntentosFallidos(u.getIntentosFallidos()+1);if(u.getIntentosFallidos()>=5){u.setBloqueadoHasta(LocalDateTime.now().plusMinutes(minutosBloqueo));u.setIntentosFallidos(0);}usuarios.save(u);throw credenciales();}u.setIntentosFallidos(0);u.setBloqueadoHasta(null);usuarios.save(u);return new LoginResponse(jwt.generar(u),jwt.expirationSeconds(),u.getRol(),u.getNombre());}
 @Transactional(readOnly=true) public TokenValidoResponse validar(String token){Claims c=jwt.validar(token);return new TokenValidoResponse(true,c.get("idUsuario",Long.class),Rol.valueOf(c.get("rol",String.class)),c.getExpiration().toInstant());}
 @Transactional(readOnly=true) public RenovacionResponse renovar(String token){Claims c=jwt.validar(token);Long id=c.get("idUsuario",Long.class);Usuario u=usuarios.findById(id).filter(Usuario::isActivo).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"TOKEN_INVALIDO","El usuario ya no está activo"));return new RenovacionResponse(jwt.generar(u),jwt.expirationSeconds());}
 public void logout(String token){jwt.validar(token);}
 private ApiException credenciales(){return new ApiException(HttpStatus.UNAUTHORIZED,"CREDENCIALES_INVALIDAS","Usuario o contraseña incorrectos");}
}
